 34	// ---------------------------------------------------------------------------
 35	// Helper: extract the "path key" used for duplicate detection
 36	// ---------------------------------------------------------------------------
 37	
 38	function pathKey(path: string | RegExp): string {
 39	  return typeof path === 'string' ? path : path.source;
 40	}
 41	
 42	// ---------------------------------------------------------------------------
 43	// Tests
 44	// ---------------------------------------------------------------------------
 45	
 46	describe('buildRoutes() — route table structural invariants', () => {
 47	
 48	  it('returns a non-empty array', () => {
 49	    expect(Array.isArray(routes)).toBe(true);
 50	    expect(routes.length).toBeGreaterThan(0);
 51	  });
 52	
 53	  it('every route has a valid HTTP method (GET, POST, PUT, PATCH, DELETE)', () => {
 54	    const VALID_METHODS = new Set(['GET', 'POST', 'PUT', 'PATCH', 'DELETE']);
 55	
 56	    const violations = routes.filter(
 57	      (route) => !VALID_METHODS.has(route.method),
 58	    );
 59	
 60	    expect(violations).toEqual([]);
 61	  });
 62	
 63	  it('every RegExp route uses only named capture groups — no positional (unnamed) groups', () => {
 64	    /**
 65	     * A positional (unnamed) capture group is an opening parenthesis `(` that is
 66	     * NOT followed by either:
 67	     *   - `?:` — non-capturing group
 68	     *   - `?<` — named capture group
 69	     *   - `?=` — positive lookahead
 70	     *   - `?!` — negative lookahead
 71	     *   - `?<=` — positive lookbehind
 72	     *   - `?<!` — negative lookbehind
 73	     *
 74	     * The regex below detects any `(` that does NOT start one of the above
 75	     * special-group syntaxes (i.e., it is a plain capturing group).
 76	     */
 77	    const POSITIONAL_GROUP_RE = /\((?!\?)/;
 78	
 79	    const violations = routes.filter((route) => {
 80	      if (typeof route.path !== 'object') return false;   // skip string routes
 81	      return POSITIONAL_GROUP_RE.test(route.path.source);
 82	    });
 83	
 84	    const violatingPatterns = violations.map((r) => ({
 85	      method: r.method,
 86	      source: (r.path as RegExp).source,
 87	    }));
 88	
 89	    expect(violatingPatterns).toEqual([]);
 90	  });
 91	
 92	  it('no two routes share the same method + path combination', () => {
 93	    const seen = new Map<string, number>();   // key → first index
 94	    const duplicates: Array<{ index: number; method: string; path: string }> = [];
 95	
 96	    routes.forEach((route, idx) => {
 97	      const key = `${route.method} ${pathKey(route.path)}`;
 98	      if (seen.has(key)) {
 99	        duplicates.push({ index: idx, method: route.method, path: pathKey(route.path) });
100	      } else {

101	        seen.set(key, idx);
102	      }
103	    });
104	
105	    expect(duplicates).toEqual([]);
106	  });
107	
108	});

